+ if(g.focus&&g.focus.until<g.time)g.focus=null;
+ for(let e of g.enemies){e.attack-=dt;e.hit=Math.max(0,e.hit-dt);let dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy)||1;e.vx+=dx/d*e.speed*dt*2.6;e.vy+=dy/d*e.speed*dt*2.6;let drag=Math.pow(.08,dt);e.vx*=drag;e.vy*=drag;e.x+=e.vx*dt;e.y+=e.vy*dt;if(d<e.r+p.r+7&&e.attack<=0){g.hp-=e.dmg; e.attack=.8; let a=Math.atan2(p.y-e.y,p.x-e.x);p.vx+=-Math.cos(a)*85;p.vy+=-Math.sin(a)*85;for(let j=0;j<5;j++)particle(p.x+rand(-10,10),p.y+rand(-10,10),'#c65e68')}}
