 function levelUp(){game.xp-=game.nextXp;game.level++;game.nextXp=Math.floor(game.nextXp*1.35+3);game.running=false;let choices=[...boons].sort(()=>Math.random()-.5).slice(0,3);$('cards').innerHTML=choices.map((b,i)=>`<button class="card" data-boon="${boons.indexOf(b)}"><span class="tag">${b.tag}</span><div class="icon">${b.icon}</div><div class="name">${b.name}</div><div class="desc">${b.desc}</div></button>`).join('');startPanel.style.display='none';upgradePanel.style.display='block';overlay.style.display='flex';$('cards').onclick=e=>{let card=e.target.closest('[data-boon]');if(!card)return;boons[+card.dataset.boon].apply(game);upgradePanel.style.display='none';overlay.style.display='none';game.running=true;last=performance.now();showToast('The horde evolves');raf=requestAnimationFrame(loop)};renderHud()}
