 function drawGround(cx,cy){ctx.fillStyle='#11131b';ctx.fillRect(0,0,W,H);let tile=64,ox=((W/2-cx)%tile+tile)%tile,oy=((H/2-cy)%tile+tile)%tile;ctx.strokeStyle='#ffffff08';ctx.lineWidth=1;ctx.beginPath();for(let x=ox;x<W;x+=tile){ctx.moveTo(x,0);ctx.lineTo(x,H)}for(let y=oy;y<H;y+=tile){ctx.moveTo(0,y);ctx.lineTo(W,y)}ctx.stroke();ctx.fillStyle='#b5946520';for(let i=0;i<30;i++){let x=((i*173+Math.floor(cx/90)*37)%W+W)%W,y=((i*97+Math.floor(cy/90)*51)%H+H)%H;ctx.fillRect(x,y,2,2)}}
